Cypher query: MATCH (p:Person)-[:CREATED]->(w:Work)
WHERE (toLower(p.name) CONTAINS "tchaikovsky" OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS "tchaikovsky"))
  AND (
    ((toLower(w.name) CONTAINS "swan" AND toLower(w.name) CONTAINS "lake") OR any(alias IN coalesce(w.aliases, []) WHERE toLower(alias) CONTAINS "swan" AND toLower(alias) CONTAINS "lake"))
    OR ((toLower(w.name) CONTAINS "sleeping" AND toLower(w.name) CONTAINS "beauty") OR any(alias IN coalesce(w.aliases, []) WHERE toLower(alias) CONTAINS "sleeping" AND toLower(alias) CONTAINS "beauty"))
    OR (toLower(w.name) CONTAINS "nutcracker" OR any(alias IN coalesce(w.aliases, []) WHERE toLower(alias) CONTAINS "nutcracker"))
  )
RETURN p.name AS composer, w.name AS ballet
LIMIT 10
