Cypher query: MATCH path = (p:Person)-[*1..2]-(place:Place)
WHERE (
  (toLower(p.name) CONTAINS "raymond" AND toLower(p.name) CONTAINS "unwin")
  OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS "raymond" AND toLower(alias) CONTAINS "unwin")
  OR (toLower(p.name) CONTAINS "barry" AND toLower(p.name) CONTAINS "parker")
  OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS "barry" AND toLower(alias) CONTAINS "parker")
)
AND toLower(place.name) CONTAINS "new"
AND toLower(place.name) CONTAINS "earswick"
